public virtual void CheckItem(ItemName itemName)
{ 
    if (itemName == requireItem && !isDone)
    {
        isDone = true;
        OnClickAction();
        PlayDialogue(correctItemDialogue);
        EventHandler.CallItemUsedEvent(itemName);
    }
}

